   253  static unsigned long
   254  coolkey_get_object_type(unsigned long object_id) { return ((object_id >> 24 ) & 0xff); }
   255
   256  static unsigned long
   257  coolkey_make_new_id(unsigned long object_id, unsigned long id_type)
   258  { return ((object_id  & 0x00ffffffUL)|(id_type << 24)); }
