   261  /*
   262   * We need cert data to fill in some of our keys. Also, some older tokens store the cert data in a separate
   263   * object from the rest of the cert attributes. This function handles both of these complications
   264   */
   265  static int
   266  coolkey_get_certificate(sc_card_t *card, sc_cardctl_coolkey_object_t *obj, struct sc_pkcs15_der *cert)
   267  {
   268          sc_cardctl_coolkey_object_t *cert_obj;
   269          unsigned long object_id;
   270          int r;
   271
   272          cert_obj = obj;
   273          if (coolkey_get_object_type(obj->id) != COOLKEY_ID_CERT) {
   274                  r = coolkey_find_matching_cert(card, obj, &cert_obj);
   275                  if (r < 0) {
   276                          return r;
   277                  }
   278          }
   279          r = coolkey_get_attribute_lv(card, cert_obj, CKA_VALUE, cert);
   280          if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
   281                  object_id = coolkey_make_new_id(cert_obj->id, COOLKEY_ID_CERT_DATA);
   282                  r = coolkey_get_object(card, object_id, &cert_obj);
   283                  if (r < 0) {
   284                          return r;
   285                  }
   286                  /* fill in cert data */
   287                  cert->value = malloc(cert_obj->length);
   288                  if (cert->value == NULL) {
   289                          return SC_ERROR_OUT_OF_MEMORY;
   290                  }
   291                  memcpy(cert->value, cert_obj->data, cert_obj->length);
   292                  cert->len = cert_obj->length;
   293                  return SC_SUCCESS;
   294          }
   295          return r;
   296  }
